#include <stdio.h>

typedef struct {
    char nom[50];
    int age;
    double salaire;
} Employe;

void afficher(Employe e) {
    printf("%s, %d ans, %.2f€\n", e.nom, e.age, e.salaire);
}

int main() {
    Employe alice = {"Alice", 30, 2500.0};
    Employe bob = {"Bob", 25, 2200.0};

    alice.salaire = 2700.0; // modification
    afficher(alice);
    afficher(bob);
    return 0;
}
